@prefix holon: <https://example.org/holon#> .
@prefix oe: <https://example.org/openevidence#> .
@prefix oeq: <https://example.org/openevidence/questions/> .
@prefix oegen: <https://example.org/openevidence/generated/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<https://example.org/openevidence/questions/q_t1> a holon:ClinicalQuestionHolon .

<https://example.org/openevidence/drugs/lisinopril> oe:treats <https://example.org/openevidence/diseases/hypertension> .
<https://example.org/openevidence/generated/ev_t1_0> a holon:EvidenceAssertion ;
    rdf:reifies <https://example.org/openevidence/generated/ev_t1_0-tt> ;
    holon:confidence "0.95"^^xsd:decimal ;
    holon:evidenceLevel "Level-1A" ;
    holon:assessedBy <https://example.org/openevidence/questions/openevidence_ai> ;
    holon:recordedOn "2026-12-31"^^xsd:date ;
    oe:cites <https://example.org/openevidence/sources/34567890> ;
    holon:inHolon <https://example.org/openevidence/questions/q_t1> ;
    oe:effectiveness "effective" .
<https://example.org/openevidence/generated/ev_t1_0-tt> rdf:subject <https://example.org/openevidence/drugs/lisinopril> ;
    rdf:predicate oe:treats ;
    rdf:object <https://example.org/openevidence/diseases/hypertension> .
